window.PPIQ_QUESTIONS=[{"id":"Q001A","chapter":1,"slide":3,"type":"single","question":"Who can create criminal law for all of Canada?","options":["Federal Parliament","Provincial police","Municipal council","Local courts"],"correct":[0],"explanation":"The federal Parliament creates Canadian criminal law."},{"id":"Q001B","chapter":1,"slide":3,"type":"tf","question":"Parliament has legislative authority over criminal law for Canada.","options":["True","False"],"correct":[0],"explanation":"The federal Parliament creates Canadian criminal law."},{"id":"Q002A","chapter":1,"slide":6,"type":"single","question":"Who mainly administers criminal justice within a province?","options":["Provincial government","Municipal library","Federal Senate","Foreign government"],"correct":[0],"explanation":"The provinces have responsibility for administering justice."},{"id":"Q002B","chapter":1,"slide":6,"type":"tf","question":"A municipal library administers criminal justice within a province.","options":["True","False"],"correct":[1],"explanation":"The provinces have responsibility for administering justice."},{"id":"Q003A","chapter":1,"slide":9,"type":"single","question":"Which constitutional law establishes the division of legislative powers?","options":["Constitution Act, 1867","Highway Traffic Act","Criminal Code","Police handbook"],"correct":[0],"explanation":"The Constitution Act, 1867 divides legislative authority."},{"id":"Q003B","chapter":1,"slide":9,"type":"tf","question":"The Constitution Act, 1867 allocates legislative powers between Parliament and provincial legislatures.","options":["True","False"],"correct":[0],"explanation":"The Constitution Act, 1867 divides legislative authority."},{"id":"Q004A","chapter":1,"slide":9,"type":"single","question":"When did the Canadian Charter become part of the Constitution?","options":["1982","1960","1867","2005"],"correct":[0],"explanation":"The Charter forms part of the Constitution Act, 1982."},{"id":"Q004B","chapter":1,"slide":9,"type":"tf","question":"The Canadian Charter became part of the Constitution in 1960.","options":["True","False"],"correct":[1],"explanation":"The Charter forms part of the Constitution Act, 1982."},{"id":"Q005A","chapter":1,"slide":9,"type":"single","question":"When was the Canadian Bill of Rights enacted?","options":["1960","1982","1867","1998"],"correct":[0],"explanation":"The Canadian Bill of Rights dates to 1960."},{"id":"Q005B","chapter":1,"slide":9,"type":"tf","question":"The Canadian Bill of Rights was enacted in 1960.","options":["True","False"],"correct":[0],"explanation":"The Canadian Bill of Rights dates to 1960."},{"id":"Q006A","chapter":1,"slide":9,"type":"single","question":"Which principle means legislation must follow the Constitution?","options":["Constitutional supremacy","Absolute police discretion","Parliamentary immunity","Informal enforcement"],"correct":[0],"explanation":"Constitution Act, 1982, section 52(1) makes the Constitution the supreme law of Canada. Inconsistent laws have no force or effect to the extent of the inconsistency."},{"id":"Q006B","chapter":1,"slide":9,"type":"tf","question":"Police discretion takes precedence over inconsistent provisions of the Constitution.","options":["True","False"],"correct":[1],"explanation":"Constitution Act, 1982, section 52(1) makes the Constitution the supreme law of Canada. Inconsistent laws have no force or effect to the extent of the inconsistency."},{"id":"Q007A","chapter":1,"slide":8,"type":"single","question":"What is a statute?","options":["Law passed by the legislature","A police personal opinion","A newspaper report","An unconfirmed rumour"],"correct":[0],"explanation":"A statute is legislation enacted by a legislature. At the federal level, the Interpretation Act distinguishes an Act of Parliament from regulations made under delegated authority."},{"id":"Q007B","chapter":1,"slide":8,"type":"tf","question":"A statute is legislation enacted by a legislature.","options":["True","False"],"correct":[0],"explanation":"A statute is legislation enacted by a legislature. At the federal level, the Interpretation Act distinguishes an Act of Parliament from regulations made under delegated authority."},{"id":"Q008A","chapter":1,"slide":8,"type":"single","question":"What is common law principally developed through?","options":["Court decisions","Police shift rosters","Newspaper stories","Municipal elections"],"correct":[0],"explanation":"Common law develops through judicial decisions. Salituro explains that judges may make appropriate incremental changes to common-law rules, while complex changes with uncertain consequences may be for the legislature."},{"id":"Q008B","chapter":1,"slide":8,"type":"tf","question":"Common law is principally developed through police shift rosters.","options":["True","False"],"correct":[1],"explanation":"Common law develops through judicial decisions. Salituro explains that judges may make appropriate incremental changes to common-law rules, while complex changes with uncertain consequences may be for the legislature."},{"id":"Q009A","chapter":1,"slide":8,"type":"single","question":"What are regulations?","options":["Rules created under legislative authority","Only police policies","A type of arrest","A witness interview"],"correct":[0],"explanation":"Regulations are delegated legislation. The federal Interpretation Act includes instruments made under authority conferred by an Act within its definition of regulation."},{"id":"Q009B","chapter":1,"slide":8,"type":"tf","question":"Regulations are rules made under delegated legislative authority.","options":["True","False"],"correct":[0],"explanation":"Regulations are delegated legislation. The federal Interpretation Act includes instruments made under authority conferred by an Act within its definition of regulation."},{"id":"Q010A","chapter":1,"slide":9,"type":"single","question":"What does Charter section 7 protect?","options":["Life, liberty and security of the person","Only search warrants","Only traffic laws","Municipal finances"],"correct":[0],"explanation":"Section 7 protects life, liberty and security of the person, and the right not to be deprived of them except in accordance with the principles of fundamental justice."},{"id":"Q010B","chapter":1,"slide":9,"type":"tf","question":"Charter section 7 protects only rights concerning search warrants.","options":["True","False"],"correct":[1],"explanation":"Section 7 protects life, liberty and security of the person, and the right not to be deprived of them except in accordance with the principles of fundamental justice."},{"id":"Q011A","chapter":1,"slide":9,"type":"single","question":"Which Charter section concerns unreasonable search and seizure?","options":["Section 8","Section 9","Section 10","Section 14"],"correct":[0],"explanation":"Section 8 protects against unreasonable searches and seizures."},{"id":"Q011B","chapter":1,"slide":9,"type":"tf","question":"Charter section 8 protects against unreasonable search and seizure.","options":["True","False"],"correct":[0],"explanation":"Section 8 protects against unreasonable searches and seizures."},{"id":"Q012A","chapter":1,"slide":9,"type":"single","question":"Which Charter section prevents arbitrary detention?","options":["Section 9","Section 8","Section 11","Section 14"],"correct":[0],"explanation":"Section 9 prohibits arbitrary detention or imprisonment."},{"id":"Q012B","chapter":1,"slide":9,"type":"tf","question":"The Charter provision prohibiting arbitrary detention is section 8.","options":["True","False"],"correct":[1],"explanation":"Section 9 prohibits arbitrary detention or imprisonment."},{"id":"Q013A","chapter":1,"slide":9,"type":"single","question":"Which Charter section provides rights upon arrest or detention?","options":["Section 10","Section 7","Section 12","Section 13"],"correct":[0],"explanation":"Section 10 contains arrest and detention rights."},{"id":"Q013B","chapter":1,"slide":9,"type":"tf","question":"Charter section 10 sets out rights that arise on arrest or detention.","options":["True","False"],"correct":[0],"explanation":"Section 10 contains arrest and detention rights."},{"id":"Q014A","chapter":1,"slide":10,"type":"single","question":"Which Charter section outlines rights of persons charged with an offence?","options":["Section 11","Section 8","Section 9","Section 14"],"correct":[0],"explanation":"Section 11 outlines rights concerning criminal proceedings."},{"id":"Q014B","chapter":1,"slide":10,"type":"tf","question":"Charter section 8 is the provision outlining the rights of persons charged with an offence.","options":["True","False"],"correct":[1],"explanation":"Section 11 outlines rights concerning criminal proceedings."},{"id":"Q015A","chapter":1,"slide":10,"type":"single","question":"Which Charter section bars cruel and unusual punishment?","options":["Section 12","Section 10","Section 8","Section 14"],"correct":[0],"explanation":"Section 12 protects against cruel and unusual treatment or punishment."},{"id":"Q015B","chapter":1,"slide":10,"type":"tf","question":"Charter section 12 protects against cruel and unusual treatment or punishment.","options":["True","False"],"correct":[0],"explanation":"Section 12 protects against cruel and unusual treatment or punishment."},{"id":"Q016A","chapter":1,"slide":10,"type":"single","question":"Which Charter section addresses self-incrimination of witnesses?","options":["Section 13","Section 8","Section 10","Section 12"],"correct":[0],"explanation":"Section 13 protects a witness against the use of their incriminating testimony to incriminate them in other proceedings, except prosecutions for perjury or contradictory evidence."},{"id":"Q016B","chapter":1,"slide":10,"type":"tf","question":"Charter section 8 is the provision limiting the use of a witness’s incriminating testimony in other proceedings.","options":["True","False"],"correct":[1],"explanation":"Section 13 protects a witness against the use of their incriminating testimony to incriminate them in other proceedings, except prosecutions for perjury or contradictory evidence."},{"id":"Q017A","chapter":1,"slide":10,"type":"single","question":"Which Charter section provides a right to an interpreter?","options":["Section 14","Section 7","Section 9","Section 13"],"correct":[0],"explanation":"Section 14 gives a party or witness who does not understand or speak the language of the proceedings, or who is deaf, the right to an interpreter’s assistance."},{"id":"Q017B","chapter":1,"slide":10,"type":"tf","question":"Charter section 14 provides interpreter rights in proceedings for qualifying parties and witnesses.","options":["True","False"],"correct":[0],"explanation":"Section 14 gives a party or witness who does not understand or speak the language of the proceedings, or who is deaf, the right to an interpreter’s assistance."},{"id":"Q018A","chapter":2,"slide":5,"type":"single","question":"Which Criminal Code section provides the general warrantless arrest power for peace officers?","options":["Criminal Code 495","Criminal Code 494","Criminal Code 487","Charter 8"],"correct":[0],"explanation":"Section 495 is the general warrantless arrest power for peace officers. Section 494 separately addresses arrest by any person; the conditions and limits of the applicable power must still be met."},{"id":"Q018B","chapter":2,"slide":5,"type":"tf","question":"The general peace-officer warrantless arrest power is in Criminal Code section 494 rather than section 495.","options":["True","False"],"correct":[1],"explanation":"Section 495 is the general warrantless arrest power for peace officers. Section 494 separately addresses arrest by any person; the conditions and limits of the applicable power must still be met."},{"id":"Q019A","chapter":2,"slide":5,"type":"single","question":"Which subsection limits arrest without warrant for certain offences?","options":["Section 495(2)","Section 494(1)","Section 487(1)","Charter section 14"],"correct":[0],"explanation":"For the offence categories listed in section 495(2), an officer shall not arrest without a warrant when the public-interest and court-attendance conditions in that subsection are satisfied."},{"id":"Q019B","chapter":2,"slide":5,"type":"tf","question":"Criminal Code section 495(2) restricts warrantless arrest for specified offence categories.","options":["True","False"],"correct":[0],"explanation":"For the offence categories listed in section 495(2), an officer shall not arrest without a warrant when the public-interest and court-attendance conditions in that subsection are satisfied."},{"id":"Q020A","chapter":2,"slide":6,"type":"single","question":"What does the subjective grounds test require?","options":["An actual officer belief","A jury conviction","Written consent","A media statement"],"correct":[0],"explanation":"The arresting officer must actually hold the required belief. Storrey also requires an objectively justifiable basis; a subjective belief alone is insufficient."},{"id":"Q020B","chapter":2,"slide":6,"type":"tf","question":"A jury conviction is required to satisfy an arresting officer’s subjective grounds test.","options":["True","False"],"correct":[1],"explanation":"The arresting officer must actually hold the required belief. Storrey also requires an objectively justifiable basis; a subjective belief alone is insufficient."},{"id":"Q021A","chapter":2,"slide":6,"type":"single","question":"What does the objective grounds test require?","options":["Facts that justify the belief to a reasonable person","Officer popularity","A guaranteed conviction","A police badge alone"],"correct":[0],"explanation":"A reasonable person placed in the officer’s position must be able to find reasonable grounds from the known facts. A guaranteed conviction is not required."},{"id":"Q021B","chapter":2,"slide":6,"type":"tf","question":"An officer’s belief must have an objectively justifiable factual foundation.","options":["True","False"],"correct":[0],"explanation":"A reasonable person placed in the officer’s position must be able to find reasonable grounds from the known facts. A guaranteed conviction is not required."},{"id":"Q022A","chapter":2,"slide":6,"type":"single","question":"What is meant by found committing?","options":["Personally detecting the offence being committed","An old arrest record","A rumour alone","An anonymous accusation alone"],"correct":[0],"explanation":"Finding a person committing an offence concerns the apparent commission perceived by the arresting person; it does not require a later conviction. The conditions of the particular arrest power still apply."},{"id":"Q022B","chapter":2,"slide":6,"type":"tf","question":"An old arrest record alone means an officer has found a person committing a current offence.","options":["True","False"],"correct":[1],"explanation":"Finding a person committing an offence concerns the apparent commission perceived by the arresting person; it does not require a later conviction. The conditions of the particular arrest power still apply."},{"id":"Q023A","chapter":2,"slide":7,"type":"single","question":"In RICE, what does R stand for?","options":["Repetition","Residence","Review","Release"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. R refers to repetition or continuation, corresponding to the concern in section 495(2)(d)(iii)."},{"id":"Q023B","chapter":2,"slide":7,"type":"tf","question":"In the RICE study mnemonic, R refers to repetition or continuation of an offence.","options":["True","False"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. R refers to repetition or continuation, corresponding to the concern in section 495(2)(d)(iii)."},{"id":"Q024A","chapter":2,"slide":7,"type":"single","question":"In RICE, what does I stand for?","options":["Identity","Incident","Indictment","Interview"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. I refers to identity, corresponding to section 495(2)(d)(i)."},{"id":"Q024B","chapter":2,"slide":7,"type":"tf","question":"In the RICE study mnemonic, I stands for Incident rather than Identity.","options":["True","False"],"correct":[1],"explanation":"RICE is a study mnemonic, not statutory wording. I refers to identity, corresponding to section 495(2)(d)(i)."},{"id":"Q025A","chapter":2,"slide":7,"type":"single","question":"In RICE, what does C stand for?","options":["Court","Custody","Code","Consent"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. C refers to court attendance, corresponding to section 495(2)(e)."},{"id":"Q025B","chapter":2,"slide":7,"type":"tf","question":"In the RICE study mnemonic, C refers to court attendance.","options":["True","False"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. C refers to court attendance, corresponding to section 495(2)(e)."},{"id":"Q026A","chapter":2,"slide":7,"type":"single","question":"In RICE, what does E stand for?","options":["Evidence","Entry","Emergency","Enforcement"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. E refers to evidence preservation, corresponding to section 495(2)(d)(ii)."},{"id":"Q026B","chapter":2,"slide":7,"type":"tf","question":"In the RICE study mnemonic, E stands for Entry rather than Evidence.","options":["True","False"],"correct":[1],"explanation":"RICE is a study mnemonic, not statutory wording. E refers to evidence preservation, corresponding to section 495(2)(d)(ii)."},{"id":"Q027A","chapter":2,"slide":8,"type":"single","question":"Which is a recognized common-law duty of police?","options":["Protection of property","Police promotion","Press interest","Parking location"],"correct":[0],"explanation":"Protecting property is among the common-law duties of police identified in Mann, alongside preserving the peace, preventing crime and protecting life. A general duty does not itself authorize every intrusion: a particular police action still needs lawful justification."},{"id":"Q027B","chapter":2,"slide":8,"type":"tf","question":"Protecting property is among the recognized common-law duties of police.","options":["True","False"],"correct":[0],"explanation":"Protecting property is among the common-law duties of police identified in Mann, alongside preserving the peace, preventing crime and protecting life. A general duty does not itself authorize every intrusion: a particular police action still needs lawful justification."},{"id":"Q028A","chapter":2,"slide":9,"type":"single","question":"What is a summary conviction offence?","options":["Generally a less serious offence category","Always a non-criminal bylaw","Always a murder charge","Always an indictable-only offence"],"correct":[0],"explanation":"Summary conviction is a Criminal Code procedure and offence classification. It is generally associated with less serious offences, but that shorthand does not determine the seriousness or penalty of every particular offence."},{"id":"Q028B","chapter":2,"slide":9,"type":"tf","question":"A summary conviction offence is always a non-criminal municipal bylaw offence.","options":["True","False"],"correct":[1],"explanation":"Summary conviction is a Criminal Code procedure and offence classification. It is generally associated with less serious offences, but that shorthand does not determine the seriousness or penalty of every particular offence."},{"id":"Q029A","chapter":2,"slide":10,"type":"single","question":"Who elects summary or indictable procedure for a hybrid offence?","options":["The Crown","An arresting citizen","The witness","The court clerk"],"correct":[0],"explanation":"For a hybrid offence, the Crown elects whether to proceed summarily or by indictment. This procedural choice is distinct from an accused’s election of mode of trial where available."},{"id":"Q029B","chapter":2,"slide":10,"type":"tf","question":"The Crown chooses whether to proceed summarily or by indictment for a hybrid offence.","options":["True","False"],"correct":[0],"explanation":"For a hybrid offence, the Crown elects whether to proceed summarily or by indictment. This procedural choice is distinct from an accused’s election of mode of trial where available."},{"id":"Q030A","chapter":2,"slide":10,"type":"single","question":"How are hybrid offences generally treated for arrest before Crown election?","options":["As indictable","As only provincial offences","As civil claims","As non-criminal"],"correct":[0],"explanation":"Hybrid offences are deemed indictable until the Crown elects summary procedure. This does not remove the restrictions on warrantless arrest in Criminal Code section 495(2)."},{"id":"Q030B","chapter":2,"slide":10,"type":"tf","question":"Before Crown election, a hybrid Criminal Code offence is treated only as a provincial offence.","options":["True","False"],"correct":[1],"explanation":"Hybrid offences are deemed indictable until the Crown elects summary procedure. This does not remove the restrictions on warrantless arrest in Criminal Code section 495(2)."},{"id":"Q031A","chapter":2,"slide":12,"type":"single","question":"What does actus reus mean?","options":["The prohibited conduct element","A witness statement","The penalty only","An arrest warrant"],"correct":[0],"explanation":"Actus reus refers to the external elements of an offence, which may include conduct, relevant circumstances and prohibited consequences."},{"id":"Q031B","chapter":2,"slide":12,"type":"tf","question":"Actus reus refers to the physical or conduct element of an offence.","options":["True","False"],"correct":[0],"explanation":"Actus reus refers to the external elements of an offence, which may include conduct, relevant circumstances and prohibited consequences."},{"id":"Q032A","chapter":2,"slide":12,"type":"single","question":"What does mens rea mean?","options":["The fault or mental element","The date of arrest","The search location","The officer name"],"correct":[0],"explanation":"Mens rea refers to the fault or mental element. The required fault depends on the offence; strict-liability and absolute-liability categories require separate analysis."},{"id":"Q032B","chapter":2,"slide":12,"type":"tf","question":"Mens rea means the date on which an arrest occurred.","options":["True","False"],"correct":[1],"explanation":"Mens rea refers to the fault or mental element. The required fault depends on the offence; strict-liability and absolute-liability categories require separate analysis."},{"id":"Q033A","chapter":2,"slide":13,"type":"single","question":"Which Charter provision includes the right to counsel?","options":["Section 10(b)","Section 9","Section 8","Section 14"],"correct":[0],"explanation":"Section 10(b) provides the right to retain and instruct counsel without delay."},{"id":"Q033B","chapter":2,"slide":13,"type":"tf","question":"Charter section 10(b) provides the right to retain and instruct counsel without delay.","options":["True","False"],"correct":[0],"explanation":"Section 10(b) provides the right to retain and instruct counsel without delay."},{"id":"Q034A","chapter":2,"slide":15,"type":"single","question":"Does every offence require police to make an arrest?","options":["No, legal restrictions and necessity matter","Yes, without exception","Only when witnesses agree","Only in a dwelling"],"correct":[0],"explanation":"An offence does not always require arrest. Section 495(2) prohibits warrantless arrest for its listed categories when its public-interest and court-attendance conditions are met."},{"id":"Q034B","chapter":2,"slide":15,"type":"tf","question":"Police must arrest a person for every offence, without exception.","options":["True","False"],"correct":[1],"explanation":"An offence does not always require arrest. Section 495(2) prohibits warrantless arrest for its listed categories when its public-interest and court-attendance conditions are met."},{"id":"Q035A","chapter":2,"slide":16,"type":"single","question":"What is voluntary accompaniment?","options":["Informed and voluntary agreement to go with police","An automatic arrest","A court order","Compulsory investigative detention"],"correct":[0],"explanation":"Accompanying police is voluntary only if the agreement is informed and free. Police words and conduct may instead create a detention if a reasonable person would not feel free to leave."},{"id":"Q035B","chapter":2,"slide":16,"type":"tf","question":"Voluntary accompaniment means informed and voluntary agreement to go with police, with freedom to refuse or leave.","options":["True","False"],"correct":[0],"explanation":"Accompanying police is voluntary only if the agreement is informed and free. Police words and conduct may instead create a detention if a reasonable person would not feel free to leave."},{"id":"Q036A","chapter":2,"slide":16,"type":"single","question":"What is the threshold for investigative detention?","options":["Reasonable suspicion","A hunch","Proof beyond reasonable doubt","A final conviction"],"correct":[0],"explanation":"Mann requires reasonable grounds to suspect that the person is connected to a particular crime and that detention is necessary in the circumstances. The detention must be brief and reasonable; a hunch is insufficient."},{"id":"Q036B","chapter":2,"slide":16,"type":"tf","question":"A hunch alone is enough to justify investigative detention.","options":["True","False"],"correct":[1],"explanation":"Mann requires reasonable grounds to suspect that the person is connected to a particular crime and that detention is necessary in the circumstances. The detention must be brief and reasonable; a hunch is insufficient."},{"id":"Q037A","chapter":2,"slide":17,"type":"single","question":"Which factor helps determine whether the arrest restrictions in Criminal Code section 495(2) apply?","options":["Offence classification","News coverage","Officer seniority","Police payroll"],"correct":[0],"explanation":"The offence classification matters because section 495(2) lists the offence categories to which its restrictions on warrantless arrest apply. Classification does not replace the other arrest grounds and public-interest conditions."},{"id":"Q037B","chapter":2,"slide":17,"type":"tf","question":"Offence classification matters when applying the arrest restrictions in Criminal Code section 495(2).","options":["True","False"],"correct":[0],"explanation":"The offence classification matters because section 495(2) lists the offence categories to which its restrictions on warrantless arrest apply. Classification does not replace the other arrest grounds and public-interest conditions."},{"id":"Q038A","chapter":2,"slide":18,"type":"single","question":"What is a bench warrant typically issued for?","options":["Failure to appear in court","A driver licence renewal","A traffic stop","A school search"],"correct":[0],"explanation":"Section 512(2) permits an arrest warrant in specified cases of non-attendance or evasion of service. A bench warrant commonly follows a failure to attend court."},{"id":"Q038B","chapter":2,"slide":18,"type":"tf","question":"A bench warrant is typically issued to renew a driver’s licence.","options":["True","False"],"correct":[1],"explanation":"Section 512(2) permits an arrest warrant in specified cases of non-attendance or evasion of service. A bench warrant commonly follows a failure to attend court."},{"id":"Q039A","chapter":2,"slide":18,"type":"single","question":"Is there a general time limit after which an arrest warrant issued under Part XVI of the Criminal Code automatically expires?","options":["No general time limit","One day","Seven days","Thirty days"],"correct":[0],"explanation":"Section 511(2) says a warrant issued under Part XVI remains in force until executed, with no required return date. It can be cancelled under subsection (2.1), and voluntary appearance can amount to execution under subsection (4)."},{"id":"Q039B","chapter":2,"slide":18,"type":"tf","question":"An arrest warrant issued under Part XVI has no automatic general expiry period, although it can be cancelled or otherwise cease to be enforceable.","options":["True","False"],"correct":[0],"explanation":"Section 511(2) says a warrant issued under Part XVI remains in force until executed, with no required return date. It can be cancelled under subsection (2.1), and voluntary appearance can amount to execution under subsection (4)."},{"id":"Q040A","chapter":2,"slide":19,"type":"single","question":"Which statute governs youth criminal justice?","options":["Youth Criminal Justice Act","Customs Act","Highway Traffic Act","Municipal Act"],"correct":[0],"explanation":"The Youth Criminal Justice Act governs youth criminal proceedings."},{"id":"Q040B","chapter":2,"slide":19,"type":"tf","question":"The Customs Act is the statute governing youth criminal proceedings.","options":["True","False"],"correct":[1],"explanation":"The Youth Criminal Justice Act governs youth criminal proceedings."},{"id":"Q041A","chapter":2,"slide":21,"type":"single","question":"What Criminal Code section sets out citizen arrest powers?","options":["494","495","487","529"],"correct":[0],"explanation":"Section 494 sets out citizen arrest powers."},{"id":"Q041B","chapter":2,"slide":21,"type":"tf","question":"Criminal Code section 494 sets out citizen-arrest powers.","options":["True","False"],"correct":[0],"explanation":"Section 494 sets out citizen arrest powers."},{"id":"Q042A","chapter":2,"slide":23,"type":"single","question":"After making a citizen arrest, what should someone do?","options":["Contact police promptly","Search the arrested person without limits","Interrogate for hours","Determine the sentence"],"correct":[0],"explanation":"Section 494(3) requires a person other than a peace officer who makes a warrantless arrest to deliver the arrested person to a peace officer forthwith. Contact police immediately to arrange that delivery."},{"id":"Q042B","chapter":2,"slide":23,"type":"tf","question":"A citizen’s arrest permits unlimited searches of the arrested person.","options":["True","False"],"correct":[1],"explanation":"Section 494(3) requires a person other than a peace officer who makes a warrantless arrest to deliver the arrested person to a peace officer forthwith. Contact police immediately to arrange that delivery."},{"id":"Q043A","chapter":3,"slide":4,"type":"single","question":"Which location distinction helps determine whether police need judicial entry authorization to make an arrest?","options":["Dwelling-house and all other places","Public and provincial","Vehicles and aircraft only","Indoors and outdoors only"],"correct":[0],"explanation":"A dwelling-house attracts strong privacy protection. Sections 529 and 529.1 address judicial authorization to enter a dwelling to arrest; a lawful exception may apply. This distinction does not itself authorize entry elsewhere."},{"id":"Q043B","chapter":3,"slide":4,"type":"tf","question":"Distinguishing dwelling-houses from other places helps identify the entry authority needed to make an arrest.","options":["True","False"],"correct":[0],"explanation":"A dwelling-house attracts strong privacy protection. Sections 529 and 529.1 address judicial authorization to enter a dwelling to arrest; a lawful exception may apply. This distinction does not itself authorize entry elsewhere."},{"id":"Q044A","chapter":3,"slide":4,"type":"single","question":"What is a dwelling-house?","options":["A place used as a residence","Any public street","Any business office","Only a courthouse"],"correct":[0],"explanation":"Section 2 includes a building or structure kept or occupied as a permanent or temporary residence, as well as specified connected buildings and mobile residential units."},{"id":"Q044B","chapter":3,"slide":4,"type":"tf","question":"Any public street is a dwelling-house under the Criminal Code.","options":["True","False"],"correct":[1],"explanation":"Section 2 includes a building or structure kept or occupied as a permanent or temporary residence, as well as specified connected buildings and mobile residential units."},{"id":"Q045A","chapter":3,"slide":9,"type":"single","question":"Which case is central to police entry into a home to arrest?","options":["R. v. Feeney","R. v. Fearon","R. v. Dyment","R. v. Chehil"],"correct":[0],"explanation":"R. v. Feeney governs important residential entry protections."},{"id":"Q045B","chapter":3,"slide":9,"type":"tf","question":"R. v. Feeney is a leading case on entering a home to arrest a person.","options":["True","False"],"correct":[0],"explanation":"R. v. Feeney governs important residential entry protections."},{"id":"Q046A","chapter":3,"slide":9,"type":"single","question":"Which right strongly protects dwelling-houses?","options":["Reasonable expectation of privacy","Freedom to park","Right to drive","Right to own an office"],"correct":[0],"explanation":"Homes have strong privacy protection."},{"id":"Q046B","chapter":3,"slide":9,"type":"tf","question":"A freedom to park is the right that protects a dwelling-house from police entry.","options":["True","False"],"correct":[1],"explanation":"Homes have strong privacy protection."},{"id":"Q047A","chapter":3,"slide":10,"type":"single","question":"What is generally needed to enter a dwelling to arrest?","options":["Judicial entry authorization unless an exception applies","Any officer request","Only a hunch","Only a licence plate"],"correct":[0],"explanation":"Feeney recognizes a general need for judicial authorization to enter a home."},{"id":"Q047B","chapter":3,"slide":10,"type":"tf","question":"Judicial entry authorization is generally needed to enter a dwelling-house to arrest, unless a lawful exception applies.","options":["True","False"],"correct":[0],"explanation":"Feeney recognizes a general need for judicial authorization to enter a home."},{"id":"Q048A","chapter":3,"slide":10,"type":"single","question":"What must police have grounds to believe about the suspect?","options":["That the suspect is inside the home","That the suspect is wealthy","That the neighbour is home","That all doors are open"],"correct":[0],"explanation":"For issuance under sections 529 and 529.1, there must be reasonable grounds to believe the person is or will be present. Section 529(2) requires reasonable grounds of actual presence immediately before entry under that authorization."},{"id":"Q048B","chapter":3,"slide":10,"type":"tf","question":"The suspect’s wealth, rather than grounds concerning presence in the home, supplies the required basis for entry authorization.","options":["True","False"],"correct":[1],"explanation":"For issuance under sections 529 and 529.1, there must be reasonable grounds to believe the person is or will be present. Section 529(2) requires reasonable grounds of actual presence immediately before entry under that authorization."},{"id":"Q049A","chapter":3,"slide":11,"type":"single","question":"What are exigent circumstances?","options":["Urgent circumstances making prior authorization impracticable","Ordinary paperwork time","Any suspicion","Any routine visit"],"correct":[0],"explanation":"Section 529.3 permits entry to arrest without an entry warrant only when its other prerequisites are met and exigency makes obtaining the warrant impracticable. Its examples concern imminent bodily harm or death and imminent loss or destruction of specified evidence."},{"id":"Q049B","chapter":3,"slide":11,"type":"tf","question":"Exigent circumstances involve urgency that can make obtaining prior authorization impracticable, subject to the applicable legal conditions.","options":["True","False"],"correct":[0],"explanation":"Section 529.3 permits entry to arrest without an entry warrant only when its other prerequisites are met and exigency makes obtaining the warrant impracticable. Its examples concern imminent bodily harm or death and imminent loss or destruction of specified evidence."},{"id":"Q050A","chapter":3,"slide":11,"type":"single","question":"What is hot pursuit?","options":["Immediate continuous pursuit recognized by law","A routine search next month","A weekly patrol","Any anonymous tip"],"correct":[0],"explanation":"Hot pursuit is a limited exception involving immediate, continuous pursuit under lawful arrest authority. Macooh addresses pursuit into a dwelling; it does not authorize a routine later entry merely to investigate."},{"id":"Q050B","chapter":3,"slide":11,"type":"tf","question":"A routine search planned for next month is hot pursuit.","options":["True","False"],"correct":[1],"explanation":"Hot pursuit is a limited exception involving immediate, continuous pursuit under lawful arrest authority. Macooh addresses pursuit into a dwelling; it does not authorize a routine later entry merely to investigate."},{"id":"Q051A","chapter":3,"slide":11,"type":"single","question":"Which is an example of a potential emergency entry situation?","options":["Urgent 911 call requiring assistance","Routine pamphlet delivery","An expired library book","A planned survey"],"correct":[0],"explanation":"Godoy recognizes emergency entry to investigate a 911 call where necessary to protect life and safety. The circumstances must justify entry, and the intrusion must remain limited to that protective purpose."},{"id":"Q051B","chapter":3,"slide":11,"type":"tf","question":"An urgent 911 call requiring assistance can justify emergency entry when the legal conditions are met.","options":["True","False"],"correct":[0],"explanation":"Godoy recognizes emergency entry to investigate a 911 call where necessary to protect life and safety. The circumstances must justify entry, and the intrusion must remain limited to that protective purpose."},{"id":"Q052A","chapter":3,"slide":12,"type":"single","question":"What does an implied invitation to knock generally permit?","options":["Approach the door and knock","Search all rooms","Force the door for any reason","Enter without permission"],"correct":[0],"explanation":"A knock does not itself authorize entering or searching."},{"id":"Q052B","chapter":3,"slide":12,"type":"tf","question":"The implied invitation to approach a door and knock also authorizes searching every room.","options":["True","False"],"correct":[1],"explanation":"A knock does not itself authorize entering or searching."},{"id":"Q053A","chapter":3,"slide":12,"type":"single","question":"How much force can police lawfully use to enter when authorized?","options":["Necessary and reasonable force","Unlimited force","Force as punishment","None under any circumstances"],"correct":[0],"explanation":"Lawful entry authority does not permit unlimited force. Section 25 protects necessary force only when the person is authorized by law and acts on reasonable grounds; the circumstances and other legal limits still matter."},{"id":"Q053B","chapter":3,"slide":12,"type":"tf","question":"Police acting under lawful entry authority may use only force justified as necessary and reasonable in the circumstances.","options":["True","False"],"correct":[0],"explanation":"Lawful entry authority does not permit unlimited force. Section 25 protects necessary force only when the person is authorized by law and acts on reasonable grounds; the circumstances and other legal limits still matter."},{"id":"Q054A","chapter":3,"slide":7,"type":"single","question":"Does a dwelling-house give absolute immunity from arrest?","options":["No","Yes","Only if rented","Only at night"],"correct":[0],"explanation":"Privacy protection does not mean immunity from a lawful arrest."},{"id":"Q054B","chapter":3,"slide":7,"type":"tf","question":"A dwelling-house gives its occupants absolute immunity from arrest.","options":["True","False"],"correct":[1],"explanation":"Privacy protection does not mean immunity from a lawful arrest."},{"id":"Q055A","chapter":3,"slide":10,"type":"single","question":"Does an ordinary arrest warrant always authorize entry into any home?","options":["No","Yes","Only during daytime","Only in Ontario"],"correct":[0],"explanation":"Separate entry authority may be required."},{"id":"Q055B","chapter":3,"slide":10,"type":"tf","question":"An ordinary arrest warrant does not always authorize entry into any home.","options":["True","False"],"correct":[0],"explanation":"Separate entry authority may be required."},{"id":"Q056A","chapter":7,"slide":7,"type":"single","question":"What is the preferred condition for a police search?","options":["Prior judicial authorization","A hunch","Media coverage","A supervisor preference alone"],"correct":[0],"explanation":"Hunter v. Southam explains the importance of prior authorization by an impartial decision-maker where feasible. Warrantless searches need a recognized legal justification; a hunch is insufficient."},{"id":"Q056B","chapter":7,"slide":7,"type":"tf","question":"A hunch is the preferred legal basis for a police search.","options":["True","False"],"correct":[1],"explanation":"Hunter v. Southam explains the importance of prior authorization by an impartial decision-maker where feasible. Warrantless searches need a recognized legal justification; a hunch is insufficient."},{"id":"Q057A","chapter":7,"slide":7,"type":"single","question":"Who normally must justify a warrantless search in court?","options":["The Crown","The accused","The victim","The witness"],"correct":[0],"explanation":"Once the relevant privacy interest is established, a warrantless search is presumed unreasonable and the Crown must justify it. Buhay applies this presumption and rejects an unsupported plain-view justification."},{"id":"Q057B","chapter":7,"slide":7,"type":"tf","question":"The Crown normally bears the burden of legally justifying a warrantless search once the relevant Charter privacy interest is established.","options":["True","False"],"correct":[0],"explanation":"Once the relevant privacy interest is established, a warrantless search is presumed unreasonable and the Crown must justify it. Buhay applies this presumption and rejects an unsupported plain-view justification."},{"id":"Q058A","chapter":7,"slide":8,"type":"single","question":"Which is a recognized search-incident-to-arrest purpose?","options":["Protect officer or public safety","Punish an accused","Search for gossip","Look at unrelated bank accounts"],"correct":[0],"explanation":"Recognized purposes include safety, protecting evidence and discovering evidence. Under Caslake, the search must genuinely serve a valid purpose connected to a lawful arrest and be reasonable."},{"id":"Q058B","chapter":7,"slide":8,"type":"tf","question":"Punishing an accused is a valid purpose of a search incident to arrest.","options":["True","False"],"correct":[1],"explanation":"Recognized purposes include safety, protecting evidence and discovering evidence. Under Caslake, the search must genuinely serve a valid purpose connected to a lawful arrest and be reasonable."},{"id":"Q059A","chapter":7,"slide":8,"type":"single","question":"Does arrest automatically permit every possible search?","options":["No","Yes","Only for hybrid offences","Only after a complaint"],"correct":[0],"explanation":"A lawful arrest does not permit every search. The officer must have an objectively reasonable purpose connected to the arrest, and the search must stay within lawful limits."},{"id":"Q059B","chapter":7,"slide":8,"type":"tf","question":"Arrest does not automatically authorize every possible search.","options":["True","False"],"correct":[0],"explanation":"A lawful arrest does not permit every search. The officer must have an objectively reasonable purpose connected to the arrest, and the search must stay within lawful limits."},{"id":"Q060A","chapter":7,"slide":9,"type":"single","question":"Why might an officer frisk an investigatively detained person?","options":["Weapon safety concerns","To gather any available evidence","To read all messages","To inventory finances"],"correct":[0],"explanation":"Detention does not automatically authorize a search. Mann requires reasonable grounds to believe officer or public safety is at risk, and a protective search that is reasonably necessary and limited to that purpose."},{"id":"Q060B","chapter":7,"slide":9,"type":"tf","question":"Investigative detention authorizes a frisk to gather any available evidence, without an independent protective justification.","options":["True","False"],"correct":[1],"explanation":"Detention does not automatically authorize a search. Mann requires reasonable grounds to believe officer or public safety is at risk, and a protective search that is reasonably necessary and limited to that purpose."},{"id":"Q061A","chapter":7,"slide":9,"type":"single","question":"What additional justification is needed for a protective frisk during investigative detention?","options":["Reasonable grounds to believe officer or public safety is at risk","Any hunch","A media tip only","No additional grounds"],"correct":[0],"explanation":"Mann requires reasonable grounds to believe that the officer’s safety or the safety of others is at risk. A protective pat-down must be reasonably necessary in the circumstances, not a general evidence search."},{"id":"Q061B","chapter":7,"slide":9,"type":"tf","question":"A protective frisk during investigative detention requires reasonable grounds to believe that officer or public safety is at risk.","options":["True","False"],"correct":[0],"explanation":"Mann requires reasonable grounds to believe that the officer’s safety or the safety of others is at risk. A protective pat-down must be reasonably necessary in the circumstances, not a general evidence search."},{"id":"Q062A","chapter":7,"slide":14,"type":"single","question":"May officers always search a car just because its driver was arrested?","options":["No","Yes","Only at night","Only when it is red"],"correct":[0],"explanation":"Arrest does not automatically authorize a vehicle search. Caslake requires an actual, objectively reasonable purpose connected to the arrest, such as safety or preserving or discovering relevant evidence. An inventory policy alone is insufficient."},{"id":"Q062B","chapter":7,"slide":14,"type":"tf","question":"Police may always search a car merely because they arrested its driver.","options":["True","False"],"correct":[1],"explanation":"Arrest does not automatically authorize a vehicle search. Caslake requires an actual, objectively reasonable purpose connected to the arrest, such as safety or preserving or discovering relevant evidence. An inventory policy alone is insufficient."},{"id":"Q063A","chapter":7,"slide":15,"type":"single","question":"Which case concerns cellphone searches incident to arrest?","options":["R. v. Fearon","R. v. Feeney","R. v. Dyment","R. v. Mercer"],"correct":[0],"explanation":"Fearon established conditions for searches of phones incident to arrest."},{"id":"Q063B","chapter":7,"slide":15,"type":"tf","question":"R. v. Fearon addresses cellphone searches incident to arrest.","options":["True","False"],"correct":[0],"explanation":"Fearon established conditions for searches of phones incident to arrest."},{"id":"Q064A","chapter":7,"slide":15,"type":"single","question":"How should a lawful phone search be limited?","options":["Tailored to its legitimate purpose","Every file without limits","Only to music","No documentation needed"],"correct":[0],"explanation":"Fearon requires a lawful arrest, an objectively reasonable valid purpose, a search tailored to that purpose, and detailed notes. For discovering evidence, prompt searching must be needed to avoid stymying or significantly hampering the investigation."},{"id":"Q064B","chapter":7,"slide":15,"type":"tf","question":"A lawful cellphone search incident to arrest permits examining every file without limits.","options":["True","False"],"correct":[1],"explanation":"Fearon requires a lawful arrest, an objectively reasonable valid purpose, a search tailored to that purpose, and detailed notes. For discovering evidence, prompt searching must be needed to avoid stymying or significantly hampering the investigation."},{"id":"Q065A","chapter":7,"slide":16,"type":"single","question":"Can valid search consent be withdrawn?","options":["Yes","No","Only by police","Only after one hour"],"correct":[0],"explanation":"Police cannot keep relying on consent after it is withdrawn."},{"id":"Q065B","chapter":7,"slide":16,"type":"tf","question":"Valid consent to a police search can be withdrawn.","options":["True","False"],"correct":[0],"explanation":"Police cannot keep relying on consent after it is withdrawn."},{"id":"Q066A","chapter":7,"slide":16,"type":"single","question":"Can a landlord automatically consent to police searching a tenant’s home?","options":["No","Yes","Only if rent is late","Only on weekdays"],"correct":[0],"explanation":"A landlord’s ownership does not by itself waive a tenant’s reasonable expectation of privacy. Reeves rejects one person waiving another’s Charter privacy rights; its facts involve a shared computer, not a landlord. That general principle explains why ownership alone is not automatic consent to search a tenant’s home. A search may still have another lawful basis."},{"id":"Q066B","chapter":7,"slide":16,"type":"tf","question":"A landlord can automatically waive a tenant’s privacy rights and consent to a police search of the tenant’s home.","options":["True","False"],"correct":[1],"explanation":"A landlord’s ownership does not by itself waive a tenant’s reasonable expectation of privacy. Reeves rejects one person waiving another’s Charter privacy rights; its facts involve a shared computer, not a landlord. That general principle explains why ownership alone is not automatic consent to search a tenant’s home. A search may still have another lawful basis."},{"id":"Q067A","chapter":7,"slide":20,"type":"single","question":"Why do teachers have some authority to search at schools?","options":["School safety and discipline","To avoid all legal rules","To earn fees","To administer criminal sentences"],"correct":[0],"explanation":"School officials’ searches may be justified by their safety and disciplinary responsibilities, but require reasonable grounds and reasonable scope. M. (M.R.) distinguishes school officials from those acting as police agents."},{"id":"Q067B","chapter":7,"slide":20,"type":"tf","question":"School safety and discipline help explain school officials’ limited authority to search students.","options":["True","False"],"correct":[0],"explanation":"School officials’ searches may be justified by their safety and disciplinary responsibilities, but require reasonable grounds and reasonable scope. M. (M.R.) distinguishes school officials from those acting as police agents."},{"id":"Q068A","chapter":7,"slide":21,"type":"single","question":"Do police gain unrestricted search powers by entering a school?","options":["No","Yes","Only after lessons","Only if a teacher agrees"],"correct":[0],"explanation":"Police do not gain unrestricted powers in a school. M. (M.R.) explains that the different standard for school officials does not replace normal standards when they act as police agents."},{"id":"Q068B","chapter":7,"slide":21,"type":"tf","question":"Entering a school gives police unrestricted search powers.","options":["True","False"],"correct":[1],"explanation":"Police do not gain unrestricted powers in a school. M. (M.R.) explains that the different standard for school officials does not replace normal standards when they act as police agents."},{"id":"Q069A","chapter":7,"slide":23,"type":"single","question":"What is important for the plain-view doctrine?","options":["Officer must be lawfully present","Officer must be undercover","Owner must leave","Search must be after midnight"],"correct":[0],"explanation":"Lawful presence is necessary but not enough by itself. Buhay rejects treating evidence inside a closed bag in a locked locker as plain view; section 489 also requires reasonable grounds concerning the thing to be seized."},{"id":"Q069B","chapter":7,"slide":23,"type":"tf","question":"Lawful police presence is one important requirement when relying on plain view.","options":["True","False"],"correct":[0],"explanation":"Lawful presence is necessary but not enough by itself. Buhay rejects treating evidence inside a closed bag in a locked locker as plain view; section 489 also requires reasonable grounds concerning the thing to be seized."},{"id":"Q070A","chapter":7,"slide":24,"type":"single","question":"What is continuity of evidence?","options":["Documenting how an exhibit was handled","A suspect diary","A warrant expiry period","A detention classification"],"correct":[0],"explanation":"Continuity tracks evidence collection, storage and transfer."},{"id":"Q070B","chapter":7,"slide":24,"type":"tf","question":"Continuity of evidence means a diary kept by the suspect.","options":["True","False"],"correct":[1],"explanation":"Continuity tracks evidence collection, storage and transfer."},{"id":"Q071A","chapter":7,"slide":19,"type":"single","question":"What grounds can justify a police drug-detection dog sniff under Chehil and MacKenzie?","options":["Reasonable suspicion","No grounds at all","Proof beyond reasonable doubt","A conviction first"],"correct":[0],"explanation":"Chehil and MacKenzie address reasonable suspicion for drug-detection dog sniffs in their particular contexts. The suspicion must rest on objectively discernible facts, not a hunch or an unparticularized possibility."},{"id":"Q071B","chapter":7,"slide":19,"type":"tf","question":"Chehil and MacKenzie address reasonable suspicion in the context of police drug-detection dog sniffs.","options":["True","False"],"correct":[0],"explanation":"Chehil and MacKenzie address reasonable suspicion for drug-detection dog sniffs in their particular contexts. The suspicion must rest on objectively discernible facts, not a hunch or an unparticularized possibility."},{"id":"Q072A","chapter":7,"slide":17,"type":"single","question":"What does exigent mean in police-search context?","options":["Urgency requiring prompt action","Convenient scheduling","A school term","A civil lawsuit"],"correct":[0],"explanation":"Exigent circumstances involve urgency, not convenience. The legal authority and all of its conditions still matter; section 529.3, for example, concerns entry into a dwelling to arrest rather than every type of search."},{"id":"Q072B","chapter":7,"slide":17,"type":"tf","question":"Convenient scheduling alone makes a police search exigent.","options":["True","False"],"correct":[1],"explanation":"Exigent circumstances involve urgency, not convenience. The legal authority and all of its conditions still matter; section 529.3, for example, concerns entry into a dwelling to arrest rather than every type of search."},{"id":"Q073A","chapter":8,"slide":6,"type":"single","question":"What does a search warrant application link together?","options":["Offence, location, items, grounds and nexus","Only officer and judge names","Only vehicle and shift","Only an anonymous tip"],"correct":[0],"explanation":"The application must justify the proposed place and evidence."},{"id":"Q073B","chapter":8,"slide":6,"type":"tf","question":"A search-warrant application must connect the offence, place, items sought and supporting grounds.","options":["True","False"],"correct":[0],"explanation":"The application must justify the proposed place and evidence."},{"id":"Q074A","chapter":8,"slide":7,"type":"single","question":"What does nexus mean in a search application?","options":["Connection between offence, evidence and place","Officer rank","Court fee","An arrest time"],"correct":[0],"explanation":"The information must connect the sought items to the search place."},{"id":"Q074B","chapter":8,"slide":7,"type":"tf","question":"Nexus in a search-warrant application means the officer’s rank.","options":["True","False"],"correct":[1],"explanation":"The information must connect the sought items to the search place."},{"id":"Q075A","chapter":8,"slide":8,"type":"single","question":"What does ITO mean?","options":["Information to Obtain","Internal Trial Order","Incident Transfer Order","Investigator Time Order"],"correct":[0],"explanation":"An ITO is sworn support for a search warrant application."},{"id":"Q075B","chapter":8,"slide":8,"type":"tf","question":"ITO stands for Information to Obtain.","options":["True","False"],"correct":[0],"explanation":"An ITO is sworn support for a search warrant application."},{"id":"Q076A","chapter":8,"slide":8,"type":"single","question":"Who is the affiant?","options":["Person who swears or affirms the ITO","A jury foreperson","The accused","A court reporter"],"correct":[0],"explanation":"The affiant swears the supporting information."},{"id":"Q076B","chapter":8,"slide":8,"type":"tf","question":"The affiant is necessarily the jury foreperson.","options":["True","False"],"correct":[1],"explanation":"The affiant swears the supporting information."},{"id":"Q077A","chapter":8,"slide":8,"type":"single","question":"What are the Three Fs for an ITO?","options":["Full, Fair and Frank","Fast, Firm and Final","Force, Fear and Facts","Find, Follow and File"],"correct":[0],"explanation":"The Three Fs summarize full, fair and frank disclosure. Araujo and Morelli require full and frank disclosure of material facts in ex parte applications; the mnemonic is not the text of section 487."},{"id":"Q077B","chapter":8,"slide":8,"type":"tf","question":"The Three Fs study expression refers to Full, Fair and Frank disclosure.","options":["True","False"],"correct":[0],"explanation":"The Three Fs summarize full, fair and frank disclosure. Araujo and Morelli require full and frank disclosure of material facts in ex parte applications; the mnemonic is not the text of section 487."},{"id":"Q078A","chapter":8,"slide":9,"type":"single","question":"What should the ITO explain about the offence?","options":["Why the affiant believes it occurred","Why the judge is popular","How many officers work nights","Where police cars are parked"],"correct":[0],"explanation":"The ITO needs specific offence facts and basis of knowledge."},{"id":"Q078B","chapter":8,"slide":9,"type":"tf","question":"An ITO justifies the alleged offence by explaining why the judge is popular.","options":["True","False"],"correct":[1],"explanation":"The ITO needs specific offence facts and basis of knowledge."},{"id":"Q079A","chapter":8,"slide":9,"type":"single","question":"Which details about the proposed search belong in the ITO?","options":["Premises and items sought","Only the vehicle fleet","Only the officer age","Only the suspect nickname"],"correct":[0],"explanation":"The ITO identifies location, offence and evidence sought."},{"id":"Q079B","chapter":8,"slide":9,"type":"tf","question":"An ITO should identify the premises to be searched and the items sought.","options":["True","False"],"correct":[0],"explanation":"The ITO identifies location, offence and evidence sought."},{"id":"Q080A","chapter":8,"slide":11,"type":"single","question":"Should material contradicting the police theory be disclosed in an ITO?","options":["Yes","No","Only on appeal","Only if requested by police chief"],"correct":[0],"explanation":"Material facts cannot be omitted merely because they weaken the police theory. Morelli applies the duty of full and frank disclosure and explains how misleading statements and omissions affect an ITO."},{"id":"Q080B","chapter":8,"slide":11,"type":"tf","question":"Material information contradicting the police theory should be concealed from an ITO.","options":["True","False"],"correct":[1],"explanation":"Material facts cannot be omitted merely because they weaken the police theory. Morelli applies the duty of full and frank disclosure and explains how misleading statements and omissions affect an ITO."},{"id":"Q081A","chapter":8,"slide":12,"type":"single","question":"Should an earlier warrant refusal that is material to a new application be disclosed?","options":["Yes","No","Only after trial","Only to journalists"],"correct":[0],"explanation":"Araujo requires full and frank disclosure of material facts in an ex parte application. Applying that duty, an earlier warrant refusal that is material to the new application should be disclosed rather than concealed. This does not mean every unrelated past application must be recounted."},{"id":"Q081B","chapter":8,"slide":12,"type":"tf","question":"An earlier warrant refusal that is material to a new application should be disclosed rather than concealed.","options":["True","False"],"correct":[0],"explanation":"Araujo requires full and frank disclosure of material facts in an ex parte application. Applying that duty, an earlier warrant refusal that is material to the new application should be disclosed rather than concealed. This does not mean every unrelated past application must be recounted."},{"id":"Q082A","chapter":8,"slide":12,"type":"single","question":"What must be disclosed about possible unconstitutional evidence collection?","options":["Relevant Charter violations","Only case numbers","Nothing","Only convictions"],"correct":[0],"explanation":"Material facts about how evidence was obtained must not be concealed. Côté discusses an ITO that hid earlier unconstitutional searches and treats that failure of full and frank disclosure as aggravating police misconduct. The applicant should disclose the material collection facts and relevant constitutional problems, rather than substitute a list of case numbers."},{"id":"Q082B","chapter":8,"slide":12,"type":"tf","question":"Case numbers alone replace the need to disclose relevant constitutional problems with evidence collection in a warrant application.","options":["True","False"],"correct":[1],"explanation":"Material facts about how evidence was obtained must not be concealed. Côté discusses an ITO that hid earlier unconstitutional searches and treats that failure of full and frank disclosure as aggravating police misconduct. The applicant should disclose the material collection facts and relevant constitutional problems, rather than substitute a list of case numbers."},{"id":"Q083A","chapter":8,"slide":13,"type":"single","question":"Is confidential informer identity generally privileged?","options":["Yes","No","Only after trial","Only if informant is police employee"],"correct":[0],"explanation":"Informer privilege generally protects identifying information once the privilege is established. Leipert explains the narrow innocence-at-stake exception; ordinary relevance does not itself override the privilege."},{"id":"Q083B","chapter":8,"slide":13,"type":"tf","question":"Confidential informer identity is generally privileged, subject to the applicable legal exceptions.","options":["True","False"],"correct":[0],"explanation":"Informer privilege generally protects identifying information once the privilege is established. Leipert explains the narrow innocence-at-stake exception; ordinary relevance does not itself override the privilege."},{"id":"Q084A","chapter":8,"slide":13,"type":"single","question":"Must a police agent be employed by police?","options":["No","Yes","Only as a court clerk","Only as a judge"],"correct":[0],"explanation":"Employment by police is not required for state agency. Broyles addresses a non-officer acting as a state agent in the right-to-silence context; agency depends on the police involvement and the facts."},{"id":"Q084B","chapter":8,"slide":13,"type":"tf","question":"A person must be employed by police to act as a police agent.","options":["True","False"],"correct":[1],"explanation":"Employment by police is not required for state agency. Broyles addresses a non-officer acting as a state agent in the right-to-silence context; agency depends on the police involvement and the facts."},{"id":"Q085A","chapter":8,"slide":14,"type":"single","question":"What does a sealing order do?","options":["Restricts disclosure of protected warrant material","Cancels all warrants","Arrests everyone","Guarantees secrecy forever"],"correct":[0],"explanation":"An issuing judicial officer may seal relevant materials."},{"id":"Q085B","chapter":8,"slide":14,"type":"tf","question":"A sealing order can restrict access to protected warrant information.","options":["True","False"],"correct":[0],"explanation":"An issuing judicial officer may seal relevant materials."},{"id":"Q086A","chapter":8,"slide":15,"type":"single","question":"For an application under section 487.1 made by telecommunication that does not produce a writing, what must the applicant explain?","options":["Why submitting the application by telecommunication that produces a writing is impracticable","Why officer is tired","Why location is popular","Why an email is easier"],"correct":[0],"explanation":"Under section 487.1(5)–(6), an applicant using a means of telecommunication that does not produce a writing must explain why using one that produces a writing is impracticable. This is not a universal requirement to explain inability to appear in person."},{"id":"Q086B","chapter":8,"slide":15,"type":"tf","question":"An officer’s tiredness alone satisfies section 487.1’s requirement to explain why a writing-producing telecommunication is impracticable.","options":["True","False"],"correct":[1],"explanation":"Under section 487.1(5)–(6), an applicant using a means of telecommunication that does not produce a writing must explain why using one that produces a writing is impracticable. This is not a universal requirement to explain inability to appear in person."},{"id":"Q087A","chapter":8,"slide":16,"type":"single","question":"What is the general rule when entering under a search warrant?","options":["Knock, identify, announce and request entry","Always silently break down the door","Always wait an hour","Enter without identification"],"correct":[0],"explanation":"Knock-and-announce is the ordinary common-law approach, subject to legally justified exceptions. Genest addresses search-warrant execution. Section 529.4 separately governs announcement exceptions for specified dwelling entries to arrest."},{"id":"Q087B","chapter":8,"slide":16,"type":"tf","question":"Knocking, identifying police, announcing the lawful purpose and requesting entry is the ordinary approach, subject to lawful exceptions.","options":["True","False"],"correct":[0],"explanation":"Knock-and-announce is the ordinary common-law approach, subject to legally justified exceptions. Genest addresses search-warrant execution. Section 529.4 separately governs announcement exceptions for specified dwelling entries to arrest."},{"id":"Q088A","chapter":8,"slide":17,"type":"single","question":"When may officers use force for entry with a valid warrant?","options":["When necessary and legally reasonable","At any time without limits","For punishment","Only when a neighbour asks"],"correct":[0],"explanation":"A valid warrant does not permit unlimited force. Section 25 requires lawful authority, reasonable grounds and necessary force; Genest addresses the reasonableness of force and entry when executing a search warrant."},{"id":"Q088B","chapter":8,"slide":17,"type":"tf","question":"A valid search warrant authorizes officers to use unlimited force at any time.","options":["True","False"],"correct":[1],"explanation":"A valid warrant does not permit unlimited force. Section 25 requires lawful authority, reasonable grounds and necessary force; Genest addresses the reasonableness of force and entry when executing a search warrant."},{"id":"Q089A","chapter":8,"slide":17,"type":"single","question":"What is no-knock entry?","options":["Entry without prior announcement","An ordinary conversation at a door","A nighttime telephone call","Arrest without handcuffs"],"correct":[0],"explanation":"No-knock means entry without prior announcement. The lack of announcement must have a lawful, fact-specific justification; the arrest-entry provisions in section 529.4 do not govern every search warrant."},{"id":"Q089B","chapter":8,"slide":17,"type":"tf","question":"No-knock entry means entry without prior announcement.","options":["True","False"],"correct":[0],"explanation":"No-knock means entry without prior announcement. The lack of announcement must have a lawful, fact-specific justification; the arrest-entry provisions in section 529.4 do not govern every search warrant."},{"id":"Q090A","chapter":8,"slide":18,"type":"single","question":"What is the Criminal Code definition of nighttime?","options":["9 p.m. to 6 a.m.","8 p.m. to 6 a.m.","10 p.m. to 5 a.m.","Midnight to noon"],"correct":[0],"explanation":"Section 2 defines night as 9 p.m. to 6 a.m. Section 488 separately requires a section 487 search warrant to be executed by day unless its conditions for nighttime execution are met."},{"id":"Q090B","chapter":8,"slide":18,"type":"tf","question":"The Criminal Code defines night as 8 p.m. to 6 a.m.","options":["True","False"],"correct":[1],"explanation":"Section 2 defines night as 9 p.m. to 6 a.m. Section 488 separately requires a section 487 search warrant to be executed by day unless its conditions for nighttime execution are met."},{"id":"Q091A","chapter":8,"slide":19,"type":"single","question":"Does a premises warrant automatically authorize full searches of everyone inside?","options":["No","Yes","Only if it is a rental","Only in winter"],"correct":[0],"explanation":"A premises warrant does not automatically permit unrestricted full searches of everyone present. A person-search needs an applicable legal power and its conditions. For example, CDSA section 11(5) requires reasonable grounds concerning specified items on the person when executing a warrant under that Act. A protective frisk has its own justification and limits."},{"id":"Q091B","chapter":8,"slide":19,"type":"tf","question":"A premises search warrant does not automatically authorize full searches of everyone present.","options":["True","False"],"correct":[0],"explanation":"A premises warrant does not automatically permit unrestricted full searches of everyone present. A person-search needs an applicable legal power and its conditions. For example, CDSA section 11(5) requires reasonable grounds concerning specified items on the person when executing a warrant under that Act. A protective frisk has its own justification and limits."},{"id":"Q092A","chapter":8,"slide":20,"type":"single","question":"Can police normally re-enter after finishing and leaving using the same search warrant?","options":["No","Yes indefinitely","Only at night","Only with two officers"],"correct":[0],"explanation":"A search warrant authorizes a search within its terms and lawful scope, not unlimited repeat entries. A completed search must be distinguished from a lawful temporary interruption."},{"id":"Q092B","chapter":8,"slide":20,"type":"tf","question":"A completed search warrant permits unlimited re-entry indefinitely.","options":["True","False"],"correct":[1],"explanation":"A search warrant authorizes a search within its terms and lawful scope, not unlimited repeat entries. A completed search must be distinguished from a lawful temporary interruption."},{"id":"Q093A","chapter":8,"slide":20,"type":"single","question":"Can a warrant specify an execution period?","options":["Yes","No","Only verbally","Only for provincial law"],"correct":[0],"explanation":"Form 5 authorizes entry and search between the hours the justice directs. The particular warrant terms therefore matter. Section 488 separately governs nighttime execution of section 487 warrants; a warrant is not permission to ignore its execution limits."},{"id":"Q093B","chapter":8,"slide":20,"type":"tf","question":"A search warrant may specify the hours during which it can be executed.","options":["True","False"],"correct":[0],"explanation":"Form 5 authorizes entry and search between the hours the justice directs. The particular warrant terms therefore matter. Section 488 separately governs nighttime execution of section 487 warrants; a warrant is not permission to ignore its execution limits."},{"id":"Q094A","chapter":8,"slide":21,"type":"single","question":"How should the information supporting a warrant be made?","options":["Under oath or affirmation","With an unsigned note","On a public forum","By telephone rumour alone"],"correct":[0],"explanation":"An ITO must be sworn or affirmed."},{"id":"Q094B","chapter":8,"slide":21,"type":"tf","question":"An unsigned public-forum post alone satisfies the sworn-information requirement for an ITO.","options":["True","False"],"correct":[1],"explanation":"An ITO must be sworn or affirmed."},{"id":"Q095A","chapter":8,"slide":21,"type":"single","question":"What does CPIC stand for?","options":["Canadian Police Information Centre","Canadian Public Inquiry Council","Central Police Investigation Court","Criminal Property Identification Code"],"correct":[0],"explanation":"CPIC stands for Canadian Police Information Centre. Yumnu uses that full name when discussing the database. Identifying the database does not itself establish authority for a search, detention or disclosure of personal information."},{"id":"Q095B","chapter":8,"slide":21,"type":"tf","question":"CPIC stands for Canadian Police Information Centre.","options":["True","False"],"correct":[0],"explanation":"CPIC stands for Canadian Police Information Centre. Yumnu uses that full name when discussing the database. Identifying the database does not itself establish authority for a search, detention or disclosure of personal information."},{"id":"M001","chapter":1,"slide":9,"type":"single","question":"Which rights are protected by the Canadian Charter?","options":["Freedom from unreasonable search","Freedom from arbitrary detention","Right to know reasons for arrest","Freedom from unreasonable search and freedom from arbitrary detention","All of the above"],"correct":[4],"explanation":"All of the above is the most complete answer because each preceding option is correct. Charter sections 8, 9 and 10 protect these rights.","answerStyle":"most_complete","pinLastOption":true},{"id":"M002","chapter":2,"slide":7,"type":"single","question":"What concerns are included in RICE — which combination gives the most complete correct answer?","options":["1 and 2","2 and 3","1, 2 and 3","1 and 4","2, 3 and 4"],"correct":[2],"explanation":"Statements 1, 2 and 3 form the most complete correct combination; statement 4 does not belong. RICE is a study mnemonic for Repetition, Identity, Court attendance and Evidence. Section 495(2) contains the underlying arrest considerations; the acronym itself is not statutory wording.","answerStyle":"most_complete","statements":["Repetition of the offence","Establishing identity","Court attendance","Officer salary"]},{"id":"M003","chapter":2,"slide":13,"type":"single","question":"Which combination lists rights provided by Charter section 10 on arrest or detention?","options":["1 and 2","2 and 3","1, 2 and 3","1 and 4","2, 3 and 4"],"correct":[2],"explanation":"Statements 1, 2 and 3 reflect Charter section 10(a), (b) and (c). They concern reasons, counsel and review of detention by habeas corpus. A promised conviction is not a Charter right. Section 10(c) provides a right to review; it is not a claim that police must give the same warning about it as section 10(b).","answerStyle":"most_complete","statements":["Be informed promptly of the reasons for the arrest or detention","Retain and instruct counsel without delay and be informed of that right","Have the validity of detention determined by habeas corpus and be released if it is unlawful","Be promised that the person will be convicted"]},{"id":"M004","chapter":3,"slide":11,"type":"single","question":"Which circumstances may create lawful exceptions to prior home entry authorization?","options":["Hot pursuit","Exigent circumstances","Certain emergency assistance","Hot pursuit and exigent circumstances","All of the above"],"correct":[4],"explanation":"All of the above is the most complete answer because each preceding option is correct. Hot pursuit, exigent entry to arrest and emergency assistance are distinct legal bases with different prerequisites. None allows entry simply because police wish to investigate.","answerStyle":"most_complete","pinLastOption":true},{"id":"M005","chapter":7,"slide":8,"type":"single","question":"Which are valid purposes of a search incident to arrest?","options":["Safety","Prevent destruction of evidence","Discover offence-related evidence","Safety and prevention of evidence destruction","All of the above"],"correct":[4],"explanation":"All of the above is the most complete answer because each preceding option is correct. Recognized purposes include safety, protecting evidence and discovering evidence. Under Caslake, the search must genuinely serve a valid purpose connected to a lawful arrest and be reasonable.","answerStyle":"most_complete","pinLastOption":true},{"id":"M006","chapter":7,"slide":15,"type":"single","question":"Which combination identifies the listed conditions addressed in R. v. Fearon cellphone searches?","options":["1 and 2","2 and 3","1, 2 and 3","1 and 4","2, 3 and 4"],"correct":[2],"explanation":"Statements 1, 2 and 3 form the most complete correct combination; statement 4 does not belong. Fearon requires a lawful arrest, an objectively reasonable valid purpose, a search tailored to that purpose, and detailed notes. For discovering evidence, prompt searching must be needed to avoid stymying or significantly hampering the investigation.","answerStyle":"most_complete","statements":["Lawful arrest","Search tailored to its purpose","Detailed notes","Unlimited browsing"]},{"id":"M007","chapter":7,"slide":24,"type":"single","question":"Which practices support continuity of evidence — which combination gives the most complete correct answer?","options":["1 and 2","2 and 3","1, 2 and 3","1 and 4","2, 3 and 4"],"correct":[2],"explanation":"Continuity depends on reliable documentation and handling.","answerStyle":"most_complete","statements":["Recording who handles exhibits","Recording where an item was found","Safe storage","Allowing unrecorded transfers"]},{"id":"M008","chapter":8,"slide":8,"type":"single","question":"Which items describe the Three Fs?","options":["Full","Fair","Frank","Full and Fair","All of the above"],"correct":[4],"explanation":"All of the above is the most complete answer because each preceding option is correct. The Three Fs summarize full, fair and frank disclosure. Araujo and Morelli require full and frank disclosure of material facts in ex parte applications; the mnemonic is not the text of section 487.","answerStyle":"most_complete","pinLastOption":true},{"id":"M009","chapter":8,"slide":9,"type":"single","question":"Which facts belong in a well-supported ITO?","options":["Description of location","Items sought","Why evidence should be there","Description of the location and the items sought","All of the above"],"correct":[4],"explanation":"All of the above is the most complete answer because each preceding option is correct. The ITO must connect the place and items to the offence through supporting grounds. The duty of full and frank disclosure also requires material contrary information; it is not limited to favourable evidence.","answerStyle":"most_complete","pinLastOption":true},{"id":"M010","chapter":8,"slide":16,"type":"single","question":"Which are steps in ordinary knock-and-announce entry — which combination gives the most complete correct answer?","options":["1 and 2","2 and 3","1, 2 and 3","1 and 4","2, 3 and 4"],"correct":[2],"explanation":"Statements 1, 2 and 3 form the most complete correct combination; statement 4 does not belong. Knock-and-announce is the ordinary common-law approach, subject to legally justified exceptions. Genest addresses search-warrant execution. Section 529.4 separately governs announcement exceptions for specified dwelling entries to arrest.","answerStyle":"most_complete","statements":["Identify officers","Announce warrant","Request entry","Automatically disable all cameras"]},{"id":"F001","chapter":1,"slide":3,"type":"cloze","question":"Complete the answer: Who can create criminal law for all of Canada?","options":["Federal Parliament","Provincial police","Municipal council","Local courts"],"correct":[0],"explanation":"The federal Parliament creates Canadian criminal law."},{"id":"F002","chapter":1,"slide":6,"type":"cloze","question":"Complete the answer: Who mainly administers criminal justice within a province?","options":["Provincial government","Municipal library","Federal Senate","Foreign government"],"correct":[0],"explanation":"The provinces have responsibility for administering justice."},{"id":"F003","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: Which constitutional law establishes the division of legislative powers?","options":["Constitution Act, 1867","Highway Traffic Act","Criminal Code","Police handbook"],"correct":[0],"explanation":"The Constitution Act, 1867 divides legislative authority."},{"id":"F004","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: When did the Canadian Charter become part of the Constitution?","options":["1982","1960","1867","2005"],"correct":[0],"explanation":"The Charter forms part of the Constitution Act, 1982."},{"id":"F005","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: When was the Canadian Bill of Rights enacted?","options":["1960","1982","1867","1998"],"correct":[0],"explanation":"The Canadian Bill of Rights dates to 1960."},{"id":"F006","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: Which principle means legislation must follow the Constitution?","options":["Constitutional supremacy","Absolute police discretion","Parliamentary immunity","Informal enforcement"],"correct":[0],"explanation":"Constitution Act, 1982, section 52(1) makes the Constitution the supreme law of Canada. Inconsistent laws have no force or effect to the extent of the inconsistency."},{"id":"F007","chapter":1,"slide":8,"type":"cloze","question":"Complete the answer: What is a statute?","options":["Law passed by the legislature","A police personal opinion","A newspaper report","An unconfirmed rumour"],"correct":[0],"explanation":"A statute is legislation enacted by a legislature. At the federal level, the Interpretation Act distinguishes an Act of Parliament from regulations made under delegated authority."},{"id":"F008","chapter":1,"slide":8,"type":"cloze","question":"Complete the answer: What is common law principally developed through?","options":["Court decisions","Police shift rosters","Newspaper stories","Municipal elections"],"correct":[0],"explanation":"Common law develops through judicial decisions. Salituro explains that judges may make appropriate incremental changes to common-law rules, while complex changes with uncertain consequences may be for the legislature."},{"id":"F009","chapter":1,"slide":8,"type":"cloze","question":"Complete the answer: What are regulations?","options":["Rules created under legislative authority","Only police policies","A type of arrest","A witness interview"],"correct":[0],"explanation":"Regulations are delegated legislation. The federal Interpretation Act includes instruments made under authority conferred by an Act within its definition of regulation."},{"id":"F010","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: What does Charter section 7 protect?","options":["Life, liberty and security of the person","Only search warrants","Only traffic laws","Municipal finances"],"correct":[0],"explanation":"Section 7 protects life, liberty and security of the person, and the right not to be deprived of them except in accordance with the principles of fundamental justice."},{"id":"F011","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: Which Charter section concerns unreasonable search and seizure?","options":["Section 8","Section 9","Section 10","Section 14"],"correct":[0],"explanation":"Section 8 protects against unreasonable searches and seizures."},{"id":"F012","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: Which Charter section prevents arbitrary detention?","options":["Section 9","Section 8","Section 11","Section 14"],"correct":[0],"explanation":"Section 9 prohibits arbitrary detention or imprisonment."},{"id":"F013","chapter":1,"slide":9,"type":"cloze","question":"Complete the answer: Which Charter section provides rights upon arrest or detention?","options":["Section 10","Section 7","Section 12","Section 13"],"correct":[0],"explanation":"Section 10 contains arrest and detention rights."},{"id":"F014","chapter":1,"slide":10,"type":"cloze","question":"Complete the answer: Which Charter section outlines rights of persons charged with an offence?","options":["Section 11","Section 8","Section 9","Section 14"],"correct":[0],"explanation":"Section 11 outlines rights concerning criminal proceedings."},{"id":"F015","chapter":1,"slide":10,"type":"cloze","question":"Complete the answer: Which Charter section bars cruel and unusual punishment?","options":["Section 12","Section 10","Section 8","Section 14"],"correct":[0],"explanation":"Section 12 protects against cruel and unusual treatment or punishment."},{"id":"F016","chapter":1,"slide":10,"type":"cloze","question":"Complete the answer: Which Charter section addresses self-incrimination of witnesses?","options":["Section 13","Section 8","Section 10","Section 12"],"correct":[0],"explanation":"Section 13 protects a witness against the use of their incriminating testimony to incriminate them in other proceedings, except prosecutions for perjury or contradictory evidence."},{"id":"F017","chapter":1,"slide":10,"type":"cloze","question":"Complete the answer: Which Charter section provides a right to an interpreter?","options":["Section 14","Section 7","Section 9","Section 13"],"correct":[0],"explanation":"Section 14 gives a party or witness who does not understand or speak the language of the proceedings, or who is deaf, the right to an interpreter’s assistance."},{"id":"F018","chapter":2,"slide":5,"type":"cloze","question":"Complete the answer: Which Criminal Code section provides the general warrantless arrest power for peace officers?","options":["Criminal Code 495","Criminal Code 494","Criminal Code 487","Charter 8"],"correct":[0],"explanation":"Section 495 is the general warrantless arrest power for peace officers. Section 494 separately addresses arrest by any person; the conditions and limits of the applicable power must still be met."},{"id":"F019","chapter":2,"slide":5,"type":"cloze","question":"Complete the answer: Which subsection limits arrest without warrant for certain offences?","options":["Section 495(2)","Section 494(1)","Section 487(1)","Charter section 14"],"correct":[0],"explanation":"For the offence categories listed in section 495(2), an officer shall not arrest without a warrant when the public-interest and court-attendance conditions in that subsection are satisfied."},{"id":"F020","chapter":2,"slide":6,"type":"cloze","question":"Complete the answer: What does the subjective grounds test require?","options":["An actual officer belief","A jury conviction","Written consent","A media statement"],"correct":[0],"explanation":"The arresting officer must actually hold the required belief. Storrey also requires an objectively justifiable basis; a subjective belief alone is insufficient."},{"id":"F021","chapter":2,"slide":6,"type":"cloze","question":"Complete the answer: What does the objective grounds test require?","options":["Facts that justify the belief to a reasonable person","Officer popularity","A guaranteed conviction","A police badge alone"],"correct":[0],"explanation":"A reasonable person placed in the officer’s position must be able to find reasonable grounds from the known facts. A guaranteed conviction is not required."},{"id":"F022","chapter":2,"slide":6,"type":"cloze","question":"Complete the answer: What is meant by found committing?","options":["Personally detecting the offence being committed","An old arrest record","A rumour alone","An anonymous accusation alone"],"correct":[0],"explanation":"Finding a person committing an offence concerns the apparent commission perceived by the arresting person; it does not require a later conviction. The conditions of the particular arrest power still apply."},{"id":"F023","chapter":2,"slide":7,"type":"cloze","question":"Complete the answer: In RICE, what does R stand for?","options":["Repetition","Residence","Review","Release"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. R refers to repetition or continuation, corresponding to the concern in section 495(2)(d)(iii)."},{"id":"F024","chapter":2,"slide":7,"type":"cloze","question":"Complete the answer: In RICE, what does I stand for?","options":["Identity","Incident","Indictment","Interview"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. I refers to identity, corresponding to section 495(2)(d)(i)."},{"id":"F025","chapter":2,"slide":7,"type":"cloze","question":"Complete the answer: In RICE, what does C stand for?","options":["Court","Custody","Code","Consent"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. C refers to court attendance, corresponding to section 495(2)(e)."},{"id":"F026","chapter":2,"slide":7,"type":"cloze","question":"Complete the answer: In RICE, what does E stand for?","options":["Evidence","Entry","Emergency","Enforcement"],"correct":[0],"explanation":"RICE is a study mnemonic, not statutory wording. E refers to evidence preservation, corresponding to section 495(2)(d)(ii)."},{"id":"F027","chapter":2,"slide":8,"type":"cloze","question":"Complete the answer: Which is a recognized common-law duty of police?","options":["Protection of property","Police promotion","Press interest","Parking location"],"correct":[0],"explanation":"Protecting property is among the common-law duties of police identified in Mann, alongside preserving the peace, preventing crime and protecting life. A general duty does not itself authorize every intrusion: a particular police action still needs lawful justification."},{"id":"F028","chapter":2,"slide":9,"type":"cloze","question":"Complete the answer: What is a summary conviction offence?","options":["Generally a less serious offence category","Always a non-criminal bylaw","Always a murder charge","Always an indictable-only offence"],"correct":[0],"explanation":"Summary conviction is a Criminal Code procedure and offence classification. It is generally associated with less serious offences, but that shorthand does not determine the seriousness or penalty of every particular offence."},{"id":"F029","chapter":2,"slide":10,"type":"cloze","question":"Complete the answer: Who elects summary or indictable procedure for a hybrid offence?","options":["The Crown","An arresting citizen","The witness","The court clerk"],"correct":[0],"explanation":"For a hybrid offence, the Crown elects whether to proceed summarily or by indictment. This procedural choice is distinct from an accused’s election of mode of trial where available."},{"id":"F030","chapter":2,"slide":10,"type":"cloze","question":"Complete the answer: How are hybrid offences generally treated for arrest before Crown election?","options":["As indictable","As only provincial offences","As civil claims","As non-criminal"],"correct":[0],"explanation":"Hybrid offences are deemed indictable until the Crown elects summary procedure. This does not remove the restrictions on warrantless arrest in Criminal Code section 495(2)."}];
